import"./style-B8NRXitV.js";window.addEventListener("scroll",()=>{const e=document.getElementById("main-nav");window.scrollY>20?(e.classList.add("shadow-md"),e.classList.replace("py-6","py-4")):(e.classList.remove("shadow-md"),e.classList.replace("py-4","py-6"))});const t=document.getElementById("check-in"),n=document.getElementById("check-out"),i=document.getElementById("booking-form");if(t&&n){const e=new Date().toISOString().split("T")[0];t.min=e,n.min=e,t.addEventListener("change",()=>{if(t.value){const c=new Date(t.value);c.setDate(c.getDate()+1),n.min=c.toISOString().split("T")[0],n.value&&n.value<=t.value&&(n.value=c.toISOString().split("T")[0])}}),i.addEventListener("submit",c=>{c.preventDefault();const a=t.value,o=n.value,s=document.getElementById("quantity").value;if(new Date(o)<=new Date(a)){alert("Check-out date must be after check-in date.");return}window.location.href=`./checkout.html?checkin=${a}&checkout=${o}&quantity=${s}`})}
